import{_ as l,a as r}from"./chunks/e0e73066491222337f0c.NMa485YX.js";import{_ as t,C as i,o,c as h,j as e,a as s,E as n,a6 as u}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"当生活变得艰难，教你如何挺过去","description":"","frontmatter":{"title":"当生活变得艰难，教你如何挺过去","originalTitle":"When Life Get’s Hard, Here’s How You Push Through","date":"2023-02-17","originalUrl":"https://thedankoe.com/letters/when-life-gets-hard-heres-how-you-push-through/","minutes":11,"sourceHash":"9e4c799e5fd466c868614de3cd5e3bd63882cc8f656b07f1cabec6ceb5a808ef","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/when-life-gets-hard-heres-how-you-push-through/"}]]},"headers":[],"relativePath":"letters/when-life-gets-hard-heres-how-you-push-through.md","filePath":"letters/when-life-gets-hard-heres-how-you-push-through.md"}'),d={name:"letters/when-life-gets-hard-heres-how-you-push-through.md"};function c(m,p,f,g,_,b){const a=i("ArticleMeta");return o(),h("div",null,[p[0]||(p[0]=e("h1",{id:"当生活变得艰难-教你如何挺过去",tabindex:"-1"},[s("当生活变得艰难，教你如何挺过去 "),e("a",{class:"header-anchor",href:"#当生活变得艰难-教你如何挺过去","aria-label":'Permalink to "当生活变得艰难，教你如何挺过去"'},"​")],-1)),n(a),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/mNlNTmFAb70?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我们活在一种妄想中，想要取得进步却不愿经历任何艰难。</p><p>我们成了“理应如何”的奴隶，而我们的“理应”就是“轻松”。</p><p>人们一想到要在酷暑中走路就会抓狂，但却能毫无怨言地走进桑拿房。</p><p>区别在于预期和意图。</p><p>当你身处严寒时，你的本能反应是打冷颤。</p><p>是去抗拒。</p><p>这说得通，对吧？</p><p>寒冷确实令人不适。</p><p>于是，我们把注意力集中在源于预期的强迫性消极想法上，并沦为我们称之为“家”的心理结构的奴隶。</p><p>但是，如果你能与它共处，顺应它，并意识到不适感本身就是人类体验的一部分……</p><p>你就会发现，你对想法的解读才是你遭受痛苦的罪魁祸首。</p><p>这个教训我已经吸取过很多次了。</p><p>第一次是在因为持有大麻被捕之后（在大学校园里，他们对这事绝不轻饶）。</p><p>第二次是我向父亲借了2000美元，刷爆了我的第一张信用卡，并为了第五年的大学学业申请了贷款。为了让我那个小小的电商生意运转起来，我在财务上毁了自己……结果却败得一塌糊涂。</p><p>第三次是在哥斯达黎加。在我的业务收入达到巅峰后，我冲动地买了一张和当时的女友飞往哥斯达黎加的机票。</p><p>后来我们关系最真实的本质暴露无遗，我们分手了，第二天就飞了回来。</p><p>所有这些经历都有一个共同点：</p><p>内心的动荡。</p><p>不是压力轻微增加的那种，而是那种让你感到被困住的动荡。</p><p>最微小的任务也变成了难以逾越的不可攀之山。</p><p>每一个想法都变成了一个将你困在心理游戏中的敌人。</p><p>隧道的尽头不再有光，你忍不住怀疑自己是否还能走得出去。</p><p>显然，人生的这些阶段并不好玩。</p><p>但是，正是在这些时刻，生活提供了一个只有通过改变方向才能领悟的教训。</p><p>所有这些重大挣扎都有几个共同点：</p><ol><li>所有由进步带来的幸福感都被剥夺了，就像高潮过后突然切入了一个新的电影场景。</li><li>我感到迷茫，几乎没有欲望去维持之前目标的进展——我已经实现了它，必须继续向前。</li><li>我进行了向内和向外的双重实验。我尝试了获得内心平静的技巧，同时设定了新目标并辅以学习和实践。</li><li>随着时间的推移，拼图渐渐完整，带来了清晰度，并把我推入了一个全新的高强度阶段。</li></ol><p>这就是我们今天要在这里拆解的内容。</p><p>为什么这很重要？</p><p>这样你就能认清自己处于人生的哪个阶段，看到隧道尽头的光亮，并避免在精疲力竭无法靠岸之前，一直在水中原地挣扎。</p><h2 id="平静与进步的平衡" tabindex="-1">平静与进步的平衡 <a class="header-anchor" href="#平静与进步的平衡" aria-label="Permalink to &quot;平静与进步的平衡&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>幸福是一种技能。</p><p>它不是别人给的，而是自己创造的。</p><p>不是理所应当的，而是争取来的。</p><p>和所有技能一样，它必须被练习、被精进，并被接纳为你生活的一部分。</p><p>如果它不能融入你现在和未来的每一天、每一周或每一个月，那你为什么还要去做？</p><p>如果你想成为一名作家、创作者 (creator) 或营销人员——你为什么不每天写作？即使你一开始拿不到报酬，你依然需要建立杠杆 (leverage)、声誉和权威，直到你能够获得报酬。</p><p>如果你想学习高影响力写作（在一个实用的环境中，帮助你为未来的工作建立杠杆），<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">去看看 2 Hour Writer</a>。</p><p>当被孤立看待时，幸福就失去了意义，因为如果没有以往不幸福的经历作为参照点，它就无法存在。</p><p><em>这就是新时代积极心理学运动的问题所在。</em></p><p>你可以整天都有积极的想法。但人们没有意识到的是，每一个积极的想法都包含着一颗消极的种子。<strong>这就是为什么几乎所有巨大的成功都发生在巨大的失败之后。</strong></p><p>你可以通过思考通向一个积极的未来，但那个未来的画面，是通过同样沉重、甚至通常更痛苦的过去锻造出来的。</p><p>没有消极的经历作为锚点，你就没有有意义的目标去追求。</p><p>你需要意识到的两种心理状态是：</p><p>存在与行动。</p><p>平静与进步。</p><p>静止与运动。</p><p>当你的注意力毫无杂念地集中在任何一种纯粹的生活方式上时，你就触及了当下的力量。</p><p><em>每个人都想要金钱、肌肉和称心如意的伴侣。</em></p><p>实现这些目标的行为感觉令人难以置信……至少在开始时是这样。</p><p>如果你的物质追求背后没有一种哲思般的掌控感，你终将被残酷地唤醒。</p><p>即使你的行为没有改变，它们背后的“为什么”却可能改变。</p><p>一个在经历艰难分手后开始健身的健美运动员，可以在力量训练这个生活的缩影中找到意义——前提是他们允许自己的心智超越对物质世界的认同。</p><p>那些确实满足了物质欲望的人，改变的只是外表，而非内在。</p><p>很多人在生理上到了60岁，但心智却依然像个正经历情绪青春期的12岁孩子。</p><p><em>佛教的核心教义是无常。</em></p><p>也就是说，没有任何事物可以被孤立并被心智永远保持在静态。</p><p>这包括想法、感觉、情绪、人、地点，以及所有我们贴上标签并期望永远不变的事物。</p><p>对意识形态、教条或其他静态心理结构的认同，是我们痛苦的根源。<strong>当它们受到威胁时，我们的幸福感也同样会受到威胁。</strong></p><p>思考并不是坏事，在遇到关键情况时往往也是必要的。</p><p>但如果不加控制，强迫性的想法会创造出一个让人无法逃脱的动荡的个人现实。</p><p><em>当人静止时，他们的思绪渴望运动。</em></p><p><em>当人运动时，他们的思绪渴望静止。</em></p><p>如果没有刻意练习，心智就会执着于过去或未来，试图让无常变为永恒。</p><p>这是不幸福的原因，但不应被妖魔化，因为那违背了初衷。</p><p>当你感到不幸福时，去观察那种感觉。接纳它。让它像“指月之指”一样，向你展示生活试图教会你的功课。从那个低谷中，去迎接即将到来的高峰。</p><p>创造这种极乐心境的活动是因人而异的。你必须去观察、假设、实验、失败、学习，并不断重复这个永无止境的过程，即便你已经取得了客观上的成功。</p><p>因为即使是那种成功，也不是永恒的。</p><h2 id="实验与高强度的周期" tabindex="-1">实验与高强度的周期 <a class="header-anchor" href="#实验与高强度的周期" aria-label="Permalink to &quot;实验与高强度的周期&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>秘诀在于让心智去顺应生命的无常，<em>而不是</em> 试图让生命去屈从心智对永恒的渴望。</p><p>当然，我们大多数人都经历过这种高强度的阶段：</p><ul><li>“天时地利人和”，一切都顺理成章，你将一个极具道理的想法付诸行动。</li><li>你的目标非常清晰，技能达到新水平，并且你很享受这个过程。</li><li>你有一种强烈的目标感。感觉一天的时间根本不够用，但你拿什么都不愿意去换这样的状态。</li></ul><p>这种纯粹进步的感觉是无与伦比的。</p><p>没有杂念，绝对清晰，一块、两块、三块地砌上砖头，去构建你对未来的愿景。</p><p>那么，用更多能带来这种体验的活动填满我们的日子，也是说得通的。</p><p>生活中的高强度阶段并不是问题所在。</p><p>它们是在一段实验阶段之后自然发生的。</p><p><em>这就是大多数人的问题所在。</em></p><p>他们没有把那段令人恐惧、消极、感到迷茫和绝望的时期看作是一个机会。</p><p>如果你能在这些挣扎的时期掌控自己的心智，消极就不会再引发痛苦。</p><p>相反，你会让自己准备好，跃入一个充满进步的全新阶段。</p><h3 id="实验的目的" tabindex="-1">实验的目的 <a class="header-anchor" href="#实验的目的" aria-label="Permalink to &quot;实验的目的&quot;">​</a></h3><p>自我实验是一劳永逸解决你问题的唯一方法。</p><p>别人可以为你的问题进行诊断并开出处方，但这忽略了开方者在视角、目标和经验上与你的差异。</p><p>想象一下，你正感到精力不济。</p><p>你在社交媒体上看到一篇文章，作者对他们提供的饮食建议充满自信和笃定（这同样适用于资金匮乏和特定的商业模式问题）。</p><p>你在寻找解决方案，他们告诉你素食主义能解决你的所有问题，而处于未开悟状态的你：</p><ul><li>改善了饮食习惯</li><li>把他们的建议奉为圭臬</li><li>看到了他们提到的效果</li></ul><p>接着，你就执迷于那种饮食理念并成为了它的传道者。你把别人通过其他途径也能取得的成果，全归功于素食主义，并把任何质疑你的人妖魔化。</p><p>显然，这很危险，也是低意识层级的典型定义。</p><p>现实中，真正发生的事与素食主义并没有直接关联：</p><ul><li>你吃了更多营养丰富的食物</li><li>你的行动是为了维持你的素食主义者身份而起效</li><li>通过遵循自律的营养方案，你获得了清晰度（而不是混乱）</li></ul><p>在这种情况下，素食主义只是一个让你理顺思绪（维持一定程度的心流 (flow) 状态）并让你遵循健康原则的模式——但你却将这一切归功于某一种具体的方法。</p><p>现在，如果你去尝试一个月素食、一个月纯肉饮食、一个月生酮饮食，再加一个月灵活饮食，你就会：</p><ul><li>在不同的饮食模式之间建立联系，以揭示健康的基本原理（模式识别 = 多巴胺）。</li><li>挑选出你喜欢的一些特定方法，这意味着它们能带来可持续的结果。</li><li>精炼出一套完美契合你个人天性的系统。</li></ul><p>然后，一旦健康生活变得毫不费力，你就可以把这套方法同样应用于你的财务、社交生活、恋爱关系、精神追求，或生活中的任何其他领域。</p><p>如果你的感情出了问题，那就去请个心理医生、看YouTube大师的视频、去静修，不断尝试各种选项，直到找到正确的解决方案。</p><p>如果你的业务没有增长，那就去买个课程、请个教练、测试一款新软件、把眼光放长远些，然后制定一个新的战略……</p><p>总有办法能解决你的问题，而当你死守某一种解决方案（这种方案很可能无法一劳永逸地解决问题）时，你就剥夺了自己这种力量。</p><p>自我实验是一个保持开放心态的过程，去创造——而不是去寻找——解决生活中无尽问题的方案。</p><p><strong>给创作者 (creators) 和独立创业者的建议：</strong> 想要在一个饱和的市场中打造出一款独一无二、全面的、能自我营销的产品或服务，靠的就是这个方法。</p><p>我们不需要更多的专家，我们需要的是具有全局观的综合者，他们能创造出新的系统，并辅以细致入微的教育。</p><h3 id="向内实验" tabindex="-1">向内实验 <a class="header-anchor" href="#向内实验" aria-label="Permalink to &quot;向内实验&quot;">​</a></h3><p>你感到迷茫，是因为你没有一个系统来维持基准水平的清晰度。</p><p>当你步入人生的新篇章时，创造清晰度应该是你的头等大事。</p><p>单是这一点就能将你的意识理顺，达到让你对未来产生掌控感的程度。</p><p>向内探寻，你要实验的主要方法是那些非物质层面的追求：</p><p>哲学、灵性或情商。</p><p>你可以去实验的技巧包括但不限于：</p><ul><li>阅读</li><li>冥想</li><li>观察</li><li>自我探究</li><li>沉思</li><li>长时间安静地散步</li></ul><p>这些活动能让你的注意力集中在当下。</p><p>正如所有技能一样，你可以通过渐进式超负荷来提升自己。</p><p>也就是说，逐渐增加挑战的难度，这样你就不会感到无聊或焦虑。无聊是因为挑战难度太低，焦虑是因为挑战难度太高。</p><p>向内实验的目标，是将其中一项活动纳入你的日常或每周惯例中。</p><p>如果你想保持这些追求带来的益处，这种练习必须是持续的、终生的，并且走在精通的道路上。</p><h3 id="向外实验" tabindex="-1">向外实验 <a class="header-anchor" href="#向外实验" aria-label="Permalink to &quot;向外实验&quot;">​</a></h3><p>你之所以感到迷茫，是因为你失去了与某个目的、目标或惯例的联系，而这些曾为你的生活带来秩序。</p><p>当你结束人生的一个篇章时，你可能不再想要以前追求的东西。这是一件好事。这意味着你在成长。</p><p>但是，没有人想在迷茫期困得太久，而摆脱它的唯一途径就是：</p><ul><li>留意新目的的蛛丝马迹，不要让生活的教训从你身边溜走。</li><li>设定一个目标，这样你就能透过该目标的视角来感知生活情境（再说一次，模式识别 = 多巴胺 = 收集拼图碎片，直到图像清晰）。</li><li>识别你与目标之间的差距，并记录下阻碍你的问题。</li><li>与该目标保持一致地去学习、构建和实验。</li></ul><p>你目前生活中最紧迫的问题是什么？</p><p>是自尊？金钱？缺乏成就感？</p><p>带着这个想法坐下来沉思吧。</p><p>现在，你是能够立刻着手解决这个问题，还是必须先解决另一个问题？</p><p>如果你缺钱又没有时间创业，那么显然你不应该创业。你要么需要尝试做预算，要么去找份新工作。</p><p>如果你正在找男朋友/女朋友，你的财务、身体和精神状况足以维持一段感情吗？如果不能，先解决其他问题。</p><p>一旦你确定了可以追求的目标，就去研究并尝试那些能让你实现目标的技巧。</p><p>如果你在构建高绩效生活方式、开启基于兴趣的业务以及加入互助社区（你可能会在那里遇到你的下一个商业伙伴）方面需要指导和教育，<a href="https://modernmastery.com/letter" target="_blank" rel="noreferrer">去看看 Modern Mastery 吧</a> —— 读者只需 5 美元即可加入。</p><h3 id="维持新基准" tabindex="-1">维持新基准 <a class="header-anchor" href="#维持新基准" aria-label="Permalink to &quot;维持新基准&quot;">​</a></h3><p>随着你在实验期不断取得进展，清晰感开始达到顶峰。</p><p>很快，最后一块拼图就会严丝合缝地就位，你将进入一个高强度期，并在相应的生命领域中达到新高。</p><p>比如达到业务收入的月度新高。</p><p>但是，要时刻注意，这个阶段终将结束。</p><p>就像健美运动中的增肌和减脂，你的“增肌期”只能维持那么久，否则就会增加太多脂肪。你会开始感到昏昏沉沉、迟钝，并且不确定是否该继续逼迫自己。</p><p>当到了该“减脂”的时候，如果没有一个完善的系统，你可能会流失很多好不容易长出来的肌肉。</p><p>我们可不希望那样。</p><p>当你准备翻过这一页时，努力将信号与噪音分离开来。</p><p>加倍投入到那些技巧、任务和行动上，这将维持你所获得的新“肌肉”基准。</p><p>整个这个过程，即：</p><ul><li>通过实验解决你的问题</li><li>对人生的新篇章获得清晰的认知</li><li>推向新高，并将过程系统化以维持成果</li></ul><p>正是生命的本质。</p><p>事实上，它只是科学方法的另一个视角。</p><p>怎么利用这些信息，由你决定。</p><p>我不过是另一个追求目标、弄清门道并把所学传授下去的普通人罢了。</p><p>我鼓励你也这样做。</p><p>– Dan</p><hr><p><a href="/en/letters/when-life-gets-hard-heres-how-you-push-through">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',150))])}const q=t(d,[["render",c]]);export{P as __pageData,q as default};
